            ['title' => 'O mne', 'slug' => 'o-mne', 'content' => '<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n        <h1 class=\"display-6 fw-bold\"> Něco málo o mne</h1>\r\n        <div class=\"col-lg-6 mx-auto\">\r\n            <p class=\"lead mb-4\">Jsem zkušený cestovatel a průvodce dětí. Rozumím respektující výchově dětí, mám nápady jak udělat dětem ze života radost a příležitost k seberozvoji.​​</p>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"container col-xxl-8 px-4 py-1\">\r\n        <div class=\"row flex-lg-row-reverse align-items-center g-5 py-5\">\r\n\r\n            <div class=\"col-lg-1 pr-1 mr-1\">\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 pr-1 mr-1\">\r\n                <div class=\"pb-1  py-0\">\r\n                    <h4 class=\"display-7\">Něco málo o mne</h4>\r\n                    <p>Přátele mi říkají AG („Ejdží“'],
            ['title' => 'Sebeřízené vzdělávání', 'slug' => 'home', 'content' => '<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n        <h1 class=\"display-6 fw-bold\"> Sebeřízené vzdělávání</h1>\r\n        <div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Vytvářím pro děti z Brna a okolí <strong>příležitosti</strong> k všestrannému rozvoji, pořádám výlety, expedice, kurzy, kroužky, věnujeme se vzdělávání, praktickým dovednostem, a dalším volnočasovým aktivitám a hrám.</p>\r\n</div>\r\n</div>\r\n<div class=\"pink-100\">\r\n<div class=\"container col-xxl-8 px-4 py-1\">\r\n<div class=\"row align-items-center g-5 py-5\"><!-- Levý sloupec: Text -->\r\n<div class=\"col-12 col-lg-6\">\r\n<h2 class=\"fw-bold lh-1 mb-3\">Putujeme přírodou a učíme se novým dovednostem</h2>\r\n<p class=\"lead mb-4\">S dětmi zkoumám svět, bádáme, učíme se a hrajeme si, se staršími dobrodruhy společně plánujeme a uskutečňujeme velká dobrodružství.</p>\r\n<p class=\"lead mb-4\">Na cestách najdou vaše děti nové přátele a zažijí spoustu zábavy a dobrodružství.</p>\r\n<a class=\"btn btn-primary btn-lg px-4\" href=\"https://dobrodruzi.cz/page.php?page=21&amp;name_page=vylety\">Výlety do přírody »</a></div>\r\n<!-- Pravý sloupec: Obrázek -->\r\n<div class=\"col-12 col-lg-6\"><img class=\"d-block mx-lg-auto img-fluid\" style=\"border-radius: 2%;\" src=\"/img/obr5.jpg\" alt=\"popis\" width=\"600\" height=\"600\" loading=\"lazy\"></div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Víc než jen zábava</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Na výletech a kurzech děti rozvíjejí sebedůvěru, samostatnost, férovost, spolupráci. Učí se žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.</p>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"bg-light  mb-5 mt-2\">\r\n<div class=\"container marketing col-xxl-8 px-4 py-5\"><!-- Three columns of text below the carousel -->\r\n<div class=\"row\">\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-hiking text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Výlety​</h3>\r\n<p class=\"fw-light\">Cestovatelské a tábornické znalosti, dovednosti přežití. Zkušený průvodce, respektující přístup a spousta zábavy.​</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"https://dobrodruzi.cz/page.php?page=21&amp;name_page=vylety\" role=\"button\">Více o výletech​ »</a></div>\r\n<!-- /.col-lg-4 -->\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Kroužky​</h3>\r\n<p class=\"fw-light\">Většinu času trávíme v pohybu, v přírodě, za každého počasí. Věnujeme se, pohybovým hrám a vzdělávacím činnostem.​</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"https://dobrodruzi.cz/page.php?page=20&amp;name_page=kurzy-lukostrelby\" role=\"button\" target=\"_blank\" rel=\"noopener\">Více i kroužcích​ »</a></div>\r\n<!-- /.col-lg-4 -->\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-campground text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Kurzy​</h3>\r\n<p class=\" fw-light\">Nabízím vzdělávací činnosti, výuku programování, sjíždění řek na nafukovacích kánojích, cestovatelské dovednosti a znalosti. ​</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"https://dobrodruzi.cz/page.php?page=10&amp;name_page=kurzy-programovani\" role=\"button\">Více o kurzech »</a></div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"container col-xxl-8 px-4 py-1\">\r\n<div class=\"row flex-lg-row-reverse align-items-center g-5 py-5\">\r\n<div class=\"col-12 col-sm-12 col-lg-6\"><img src=\"/img/knihy.png\" class=\"d-block mx-lg-auto img-fluid\" alt=\"popis\" width=\"600\" height=\"600\" loading=\"lazy\"></div>\r\n<div class=\"col-lg-6\">\r\n<h3 class=\"display-7 fw-bold lh-1 mb-3\">Respekt, svoboda, zodpovědnost​</h3>\r\n<p class=\"lead\">Klíčem ke spokojenému životu jsou dobré mezilidské vztahy, ty představují zdroj většiny radostí i bolestí v lidském životě. Mladí dobrodruzi pěstují vztahy založené na vzájemném respektu a úctě.​</p>\r\n<div class=\"d-grid gap-2 d-md-flex justify-content-md-start\"><a href=\"https://www.peoplecomm.cz/respektovat-a-byt-respektovan\" type=\"button\" class=\"btn btn-outline-secondary\">Respektovat a být res. »</a> <a href=\"https://www.peoplecomm.cz/kniha-summerhill\" type=\"button\" class=\"btn btn-outline-secondary\">Demokratická škola »</a> <a href=\"https://www.peoplecomm.cz/svoboda-uceni\" type=\"button\" class=\"btn btn-outline-secondary\">​​Svoboda učení »</a></div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"text-black px-4 pt-5 pb-5 mt-5 my-5 text-center bg-light\">\r\n<h1 class=\"display-6\">Dávám možnost říct<span class=\"text-primary\"> „ne“</span></h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a potřeb, následně společně tvoříme přijatelná řešení. Akceptuji volbu a přirozené následky.</p>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\" container px-4 py-5\" id=\"hanging-icons\">\r\n<div class=\"row g-4 py-5 row-cols-1 row-cols-lg-2\">\r\n<div class=\"col d-flex align-items-start\">\r\n<div class=\"icon-square text-dark flex-shrink-0 me-3\"><i class=\"fas fas fa-arrows-alt text-primary rounded\" style=\"font-size: 45px; padding: 0px;\"> </i></div>\r\n<div>\r\n<h4 class=\"display-7\">Připravuji řízený program formou nabídky</h4>\r\n<p>Využívám <b>vnitřní motivace</b> dětí, aby se mohly věnovat věcem proto, že v nich vidí <b>smysl</b>, že je baví a že samy chtějí.</p>\r\n</div>\r\n</div>\r\n<div class=\"col d-flex align-items-start\">\r\n<div class=\"icon-square text-dark flex-shrink-0 me-3\"><i class=\"fas fas fa-handshake text-primary  rounded\" style=\"font-size: 45px; padding: 0px;\"> </i></div>\r\n<div>\r\n<h4 class=\"display-7\">„Jsem pro děti parťák, nikoli diktátor“</h4>\r\n<p>Děti vedu k samostatnosti, přistupuji k nim individuálně a s <b>respektem</b>. Zajišťuji bezpečné a motivující prostředí, ve kterém se mohou všestranně rozvíjet. Dávám jim prostor pro volnou hru a svobodné učení.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Učíme se prostřednictvím přírody</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Volnočasové aktivity organizuji převážně v přírodě, protože pobyt venku a pohyb na čerstvém vzduchu podporuje zdraví a odolnost dětí. Děti poznávají okolí místa, kde žijí, osvojují si praktické cestovatelské dovednosti a učí se rozpoznat přirozená nebezpečí.</p>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"container px-4 py-0\" id=\"featured-3\">\r\n<div class=\"row g-4 py-5 row-cols-1 row-cols-lg-3\">\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/sm-b1.jpg\" alt=\"\" class=\"img-fluid\"></p>\r\n<!--<h3 class=\"fs-5\"></h3>-->\r\n<p class=\"fw-light lh-base\">Děti se učí žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"/img/b1.jpg\" target=\"_blank\" role=\"button\" rel=\"noopener\">Zobrazit obrázek</a></div>\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/sm-b4.jpg\" alt=\"\" class=\"img-fluid\"></p>\r\n<!--<h3 class=\"fs-5\"></h3>-->\r\n<p class=\"fw-light lh-base\">Vytvářejí si pozitivní vztah sami k sobě, a neustále na sobě pracují. Podporujeme jejich kreativitu a zručnost.</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"/img/b4.jpg\" target=\"_blank\" role=\"button\" rel=\"noopener\">Zobrazit obrázek</a></div>\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/sm-b2.jpg\" alt=\"\" class=\"img-fluid\"></p>\r\n<!--<h3 class=\"fs-5\"></h3>-->\r\n<p class=\"fw-light lh-base\">Poznávají hodnotu přátelství a sdílení, prožívají společně rituály. Osvojují si správné řešení konfliktů a efektivní komunikaci.</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"/img/b2.jpg\" target=\"_blank\" role=\"button\" rel=\"noopener\">Zobrazit obrázek</a></div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"bg-light  mb-5 mt-2\">\r\n<div class=\"container marketing col-xxl-8 px-4 py-5\"><!-- Three columns of text below the carousel -->\r\n<div class=\"row\">\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-map-marked-alt text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Místa konání​</h3>\r\n<p class=\"fw-light\">Scházíme se v Brně a okolí, nejlepší učebna je sama příroda, v zimě hledáme úkryt v různých ​ <a href=\"https://goo.gl/maps/itTNU4573LkMN6Jj7\">klubovnách.</a></p>\r\n</div>\r\n<!-- /.col-lg-4 -->\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-calendar-alt text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Termíny akcí​</h3>\r\n<p class=\"fw-light\">Na výlety vyrážíme o víkendech, kurzy a kroužky se konají ve všední dny. ​ <a href=\"https://dobrodruzi.cz/page.php?page=4\">Zobrazit kalendář</a></p>\r\n</div>\r\n<!-- /.col-lg-4 -->\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-hand-holding-heart text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Ceny​</h3>\r\n<p class=\" fw-light\">Dopravu, jídlo a ubytování na výletech si hradí děti sami (výdaje v řádu stokorun'],
            ['title' => 'Nabízím', 'slug' => 'nabizim', 'content' => '<p>Kurzy, kroužky, výlety</p>', 'published' => '1', 'created_at' => '2025-04-03 04:27:35', 'updated_at' => '2025-04-03 17:20:17'],
            ['title' => 'Kurzy programování', 'slug' => 'kurzy-programovani', 'content' => '<div class=\"px-4 py-1 my-5 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Soukromé kurzy programování</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Děti učím programovat, vytváříme počítačové hry, a trávíme čas ve zdravém prostředí.</p>\r\n</div>\r\n</div>\r\n<div class=\" bg-light\">\r\n<div class=\"container px-4 mt-4 mt-5 my-4 py-0\">\r\n<div class=\" row g-4 py-5 row-cols-1 row-cols-lg-6\">\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-laptop-code text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kurz</h4>\r\n<p class=\" fw-light\">pro 1/2 účastníky</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-thumbs-up  text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Věk</h4>\r\n<p class=\"fw-light\">od 8 do 15 let</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-hand-holding-heart text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Cena</h4>\r\n<p class=\"fw-light\">1 os. / měsíc / 1000 Kč</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-user-clock text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Délka lekce</h4>\r\n<p class=\" fw-light\">2 hodiny jednou týdně</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-calendar-alt text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kdy</h4>\r\n<p class=\" fw-light\"><a href=\"https://dobrodruzi.cz/index.php?page=6\" target=\"_blank\" rel=\"noopener\">volné termíny</a></p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fa-duotone fa-motorcycle text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kde</h4>\r\n<p class=\" fw-light\">dorazím na Vámi určené místo v Brně a okolí <a href=\"https://goo.g