            ['title' => 'Výlet na míru', 'slug' => 'vylety', 'content' => '<div class=\"px-4 py-1 my-1 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Připravím výlet na míru</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Nabízím dětem zážitky a příležitosti k osobnímu rozvoji</p>\r\n</div>\r\n</div>\r\n\r\n\r\n<div class=\"pink-100\">\r\n<div class=\"container col-xxl-8 px-4 py-1\">\r\n<div class=\"row align-items-center g-5 py-5\"><!-- Levý sloupec: Text -->\r\n<div class=\"col-12 col-lg-6\">\r\n<h2 class=\"fw-bold lh-1 mb-3\">Mladé dobrodruhy učím základním cestovatelským dovednostem</h2>\r\n<p class=\"lead mb-4\">Při cestování, získávají praktické dovednosti: jak číst v jízdních řádech a hledat spoje nebo jak se orientovat podle mapy, ať už jsme ve městě či v lese.</p>\r\n<p class=\"lead mb-4\">Učíme se i tábornickým dovednostem, jak se ochránit před deštěm a proti prochladnutí, jak postavit stan, jak rozdělat oheň a uvařit si jídlo.​​​</p>\r\n<a class=\"btn btn-primary btn-lg px-4\" href=\"#\">Objednat soukromou akci​ »</a></div>\r\n<!-- Pravý sloupec: Obrázek -->\r\n<div class=\"col-12 col-lg-6\"><img class=\"d-block mx-lg-auto img-fluid\" style=\"border-radius: 2%;\" src=\"/img/vylet2.jpg\" alt=\"popis\" width=\"600\" height=\"600\" loading=\"lazy\"></div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\" bg-light\">\r\n<div class=\"container px-4 mt-4 mt-5 my-4 py-0\">\r\n<div class=\" row g-4 py-5 row-cols-1 row-cols-lg-6\">\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kurz cestování</h4>\r\n<p class=\" fw-light\">pro 1 až 6 účastníků</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-thumbs-up  text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Věk</h4>\r\n<p class=\"fw-light\">od 6 do 15 let</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-hand-holding-heart text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Cena</h4>\r\n<p class=\"fw-light\">1500 Kč / 1 den / 1 až 6 os.</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-user-clock text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Délka kurzu</h4>\r\n<p class=\" fw-light\">1 až 4 dny</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-calendar-alt text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kdy</h4>\r\n<p class=\" fw-light\">především o víkendech</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-map-marker-check text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kde</h4>\r\n<p class=\" fw-light\">Brno a okolí, ČR</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">S profesionálním průvodcem budou mít pomocnou ruku</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Provázím mladé dobrodruhy na cestách za poznáním, a zajišťuji bezpečné putování</p>\r\n</div>\r\n</div>\r\n<div class=\"container px-4 py-0\" id=\"featured-3\">\r\n<div class=\"row g-4 py-5 row-cols-1 row-cols-lg-3\">\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/b8.jpg\" alt=\"image_kid\" class=\"img-fluid\"></p>\r\n</div>\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/b20.jpg\r\n\" alt=\"image_kid\" class=\"img-fluid\"></p>\r\n</div>\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/b19.jpg\" alt=\"image_kid\" class=\"img-fluid\"></p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"mb-5 mt-2\">\r\n<div class=\"container marketing col-xxl-8 px-4 py-5\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-calendar-alt  text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>KDY</h5>\r\n<p class=\"fw-light\">Na výlet či na expedici (průzkumnou výpravu do n