            ['title' => 'Vodácký výlet', 'slug' => 'vodacky-vylet', 'content' => '<div class=\"px-4 py-1 my-5 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Dobrodružství na vodě</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Kurz je vhodný pro úplné začátečníky.</p>\r\n</div>\r\n</div>\r\n<div class=\" bg-light\">\r\n<div class=\"container px-4 mt-4 mt-5 my-4 py-0\">\r\n<div class=\" row g-4 py-5 row-cols-1 row-cols-lg-6\">\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Pro</h4>\r\n<p class=\" fw-light\">2 až 3 účastníky</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-thumbs-up  text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Věk</h4>\r\n<p class=\"fw-light\">od 6 do 15 let</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-hand-holding-heart text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Cena</h4>\r\n<p class=\"fw-light\">1 den / 1 os. / 1000 Kč</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-user-clock text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Délka kurzu</h4>\r\n<p class=\" fw-light\">1 až 3 dny</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-calendar-alt text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kdy</h4>\r\n<p class=\" fw-light\">především o víkendech</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-map-marker-check text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kde</h4>\r\n<p class=\" fw-light\">Brno a okolí, ČR</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\" container px-4 py-5\" id=\"hanging-icons\">\r\n<div class=\"row g-4 py-5 row-cols-1 row-cols-lg-2\">\r\n<div class=\"col d-flex align-items-start\">\r\n<div class=\"icon-square text-dark flex-shrink-0 me-3\"><i class=\"fa-duotone fa-icons text-primary rounded\" style=\"font-size: 45px; padding: 0px;\"> </i></div>\r\n<div>\r\n<h4 class=\"display-7\">„Připravím akci na míru“</h4>\r\n<p class=\"lead\" style=\"text-align: justify; text-justify: inter-character;\">Naplánuji výlet a zajistím veškerý servis. V ceně jsou zahrnuté všechny potřebné náklady: doprava, jídlo, profesionální průvodcovské služby, lodě, samozřejmostí je i bezpečnostní vybavení pro každého účastníka.</p>\r\n</div>\r\n</div>\r\n<div class=\"col d-flex align-items-start\">\r\n<div class=\"icon-square text-dark flex-shrink-0 me-3\"><i class=\"fa-duotone fa-hand-sparkles text-primary  rounded\" style=\"font-size: 45px; padding: 0px;\"> </i></div>\r\n<div>\r\n<h4 class=\"display-7\">Dobrodružství na dosah ruky</h4>\r\n<p class=\"lead\" style=\"text-align: justify; text-justify: inter-character;\">I když se to nezdá, nemusíme za vodáckým dobrodružstvím cestovat stovky kilometrů, řeky kousek od Brna nabízí spoustu pěkných a vodácky zajímavých úseků. Nafukovací kánoe Pálava jsou určeny pro 2 osoby, a však může vést i dalšího malého námořníka uprostřed lodě.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"container px-4 py-0\" id=\"featured-3\">\r\n<div class=\"row g-4 py-5 row-cols-1 row-cols-lg-3\">\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/voda1.jpg\" alt=\"image_kid\" class=\"img-fluid\"></p>\r\n</div>\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/voda2.jpg\" alt=\"image_kid\" class=\"img-fluid\"></p>\r\n</div>\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/voda3.jpg\" alt=\"image_kid\" class=\"img-fluid\"></p>\r\n</div>\r\n</div>\r\n</div>', 'published' => '1', 'created_at' => '2025-04-03 17:47:43', 'updated_at' => '2025-04-03 17:47:43'],
            ['title' => 'Lukostřelecké kurzy', 'slug' => 'lukostrelecke-kurzy', 'content' => '<div class=\"px-4 py-1 my-5 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">STŘÍLÍME PŘEDEVŠÍM PRO RADOST</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Trénujeme soustředění, budujeme zodpovědnost, netrénujeme profesionální střelbu, jde nám o dobrou partu a poznání.</p>\r\n</div>\r\n</div>\r\n<div class=\" bg-light\">\r\n<div class=\"container px-4 mt-4 mt-5 my-4 py-0\">\r\n<div class=\" row g-4 py-5 row-cols-1 row-cols-lg-6\">\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kurz</h4>\r\n<p class=\" fw-light\">pro 1 až 4 účastníky</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-thumbs-up  text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Věk</h4>\r\n<p class=\"fw-light\">od 8 do 15 let</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-hand-holding-heart text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Cena</h4>\r\n<p class=\"fw-light\">1 lekce / až 4 os. / 800 Kč</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-user-clock text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Délka lekce</h4>\r\n<p class=\" fw-light\">2 hodiny</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-calendar-alt text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kdy</h4>\r\n<p class=\" fw-light\">o víkendech dle domluvy</p>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-map-marker-check text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h4 class=\"fw-bold\">Kde</h4>\r\n<p class=\" fw-light\">Brno a okolí</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"container px-4 py-0\" id=\"featured-3\">\r\n<div clas